-- WhatsNew.lua: generated from CHANGELOG.md by the release (make_whatsnew.py; do not edit by hand).
-- Per version: v, date, items = { { s = "add"|"chg"|"fix", fr = { title, text }, en = { title, text } } }
local _, ns = ...
ns.WHATSNEW = {
  { v = "1.0.0-beta.197", date = "2026-11-22", items = {
    { s = "chg", fr = { "L'accueil a une section « Cette semaine »", "Deux cartes côte à côte, l'hebdo PvE et l'hebdo PvP, avec le temps restant avant la remise à zéro. L'hebdo PvE, c'est le sac de l'Undermine : où tu en es (à faire, en cours, faite), ce qu'il faut ramener des trois ailes de Hache-Tripes, où aller (Pix Xizzix, Baie-du-Butin), ce que ça rapporte (10 à 100 po), « Y aller » avec le GPS et « Voir le guide ». L'hebdo PvP donne le champ de bataille en bonus d'après le calendrier du jeu et son maître de guerre, la quête Field of Honor, ce que ça rapporte, ta place au classement de la guilde, « Y aller » et « Champs de bataille »." }, en = { "Home has a \"This week\" section", "The PvE weekly (Undermine Satchel: where you stand, what, where, reward, GPS and its guide) and the PvP weekly (bonus battleground, Field of Honor, reward, guild ranking), with the time left before the weekly reset." } },
    { s = "chg", fr = { "Un accueil mieux équilibré", "Les activités tiennent en deux lignes de deux cartes (Progresser, Argent et métiers, Guilde et groupes, Voyager), même sur une fenêtre large. La carte PvP, presque vide, laisse sa place à l'hebdo PvP. « Nous écrire » devient un bandeau fin en bas de la page." }, en = { "A more balanced Home", "The activities fit in two rows of two cards, the near-empty PvP card gives way to the PvP weekly, and \"Write to us\" becomes a thin strip at the bottom." } },
    { s = "chg", fr = { "L'hebdo n'est plus dans l'onglet Quêtes", "Du choix des guides : il est sur l'accueil. La recherche du choix des guides le trouve encore." }, en = { "The weekly left the guide picker's Quests tab (it is on Home now); the picker's search still finds it.", "" } },
    { s = "chg", fr = { "Le guide des réputations se trouve enfin", "Une ligne « Réputations » dans la carte Progresser de l'accueil, et une entrée dans le menu de gauche sous Progresser. Les deux ouvrent directement l'onglet Réputations." }, en = { "The reputations guide is easy to find", "A \"Reputations\" line in Home's Progress card and an entry under Progress in the left menu, both opening the Reputations tab." } },
    { s = "add", fr = { "Réputations : la liste des quêtes", "La carte de chaque faction liste ses quêtes, cochées si elles sont faites, \"en cours\" si elles sont dans ton journal, avec le rang requis sinon. Pour l'instant Grumegueule (37 quêtes, d'après le guide de réputation de Wowhead WoW Forever)." }, en = { "Each reputation card lists the faction's quests, ticked when done (Timbermaw Hold for now).", "" } },
  } },
  { v = "1.0.0-beta.196", date = "2026-11-22", items = {
    { s = "fix", fr = { "Plus de quête que tu ne peux pas prendre à cause de ta réputation", "Une quête qui demande une réputation que tu n'as pas sort du trajet. Elle apparaît comme verrouillée, avec la raison (« réputation Timbermaw Hold requise : Neutre »), et revient dès que tu l'as. Ça concerne d'abord les quêtes de Blackmaw Hold en Azshara (Neutre avec Grumegueule), sauf The Legashi Threat qui se prend sans réputation. Une quête déjà dans ton journal reste dans le trajet." }, en = { "A quest that needs a reputation you do not have leaves the route, locked with the reason, and comes back once you have it (Blackmaw Hold's Azshara quests: Neutral with Timbermaw Hold).", "" } },
  } },
  { v = "1.0.0-beta.195", date = "2026-11-22", items = {
    { s = "add", fr = { "Blackmaw Hold : le début de la chaîne et la réputation", "The Legashi Threat (Ekkal, en Azshara) commence tout et ne demande aucune réputation. Report to Rageroar et Missing Blackmaw Scouts (Horde) mènent ensuite à Korsa. Les quêtes de Gatekeeper Rageroar et de Gorn One Eye disent maintenant qu'il faut être Neutre avec Grumegueule. La note d'Ekkal explique le plus rapide pour y arriver : Legashi Horns, 5 cornes pour 100 de réputation. Lu sur Wowhead WoW Forever (pages des quêtes et guide de réputation Grumegueule)." }, en = { "Blackmaw Hold", "The Legashi Threat starts the chain with no reputation needed; Report to Rageroar and Missing Blackmaw Scouts lead to Korsa; Rageroar's and Gorn's quests say Neutral with Timbermaw Hold is needed, and how to get there fast (Legashi Horns)." } },
  } },
  { v = "1.0.0-beta.194", date = "2026-11-22", items = {
    { s = "add", fr = { "/wlh gearscan", "Relève dans ton jeu les objets des listes BiS de Naowh que WL Helper Gear ne connaît pas (sets de Forever, Mark of Fordring, certains bijoux et armes). Il garde leurs statistiques, leur emplacement, leur niveau et les lignes de leur infobulle (effets « Utiliser » et « Chance quand vous touchez »). Fais /reload ensuite pour enregistrer. Ça sert à compléter WL Helper Gear avec les vraies valeurs du jeu. Rien n'est envoyé." }, en = { "/wlh gearscan reads in your game the BiS items WL Helper Gear does not list (stats, slot, level, tooltip lines), saved after a /reload, to complete Gear with the game's own values.", "" } },
  } },
  { v = "1.0.0-beta.193", date = "2026-11-22", items = {
    { s = "chg", fr = { "Les flèches suivent la liste BiS", "Quand l'objet de ton sac et celui que tu portes sont tous les deux dans la liste BiS de Naowh pour ta spé, c'est l'ordre de la liste qui décide de la flèche verte, plus le calcul de WL Helper. L'infobulle le dit : « Liste BiS de Naowh : n°2, mieux que ton objet (n°5). À prendre. » ou « ... moins bien que ton objet. Garde le tien. ». Si l'un des deux n'est pas dans la liste, rien ne change. Les armes gardent le calcul." }, en = { "When both the bag item and the worn one are in Naowh's BiS list for your spec, the list's order decides the arrow; the tooltip gives both ranks.", "" } },
    { s = "chg", fr = { "WL Helper Gear deux fois plus léger", "Chaque objet ne garde plus que ses statistiques non nulles. La mémoire passe d'environ 20 Mo à 10 Mo, avec exactement les mêmes notes (vérifiées sur les 28 spés)." }, en = { "WL Helper Gear keeps only each item's non-zero stats", "About 20 MB down to 10 MB, same scores." } },
  } },
  { v = "1.0.0-beta.192", date = "2026-11-22", items = {
    { s = "add", fr = { "Le parcours dans les rapports", "WL Helper note les quêtes prises et rendues (avec l'étape du guide à ce moment-là) et les boss tués en donjon, avec le temps depuis l'entrée. En sortant d'un donjon (après au moins 5 minutes dedans), il envoie en silence un rapport « parcours » : le donjon, sa durée, l'ordre des boss et les quêtes. Ça sert à vérifier l'ordre des guides avec de vraies parties. Par la guilde, à l'auteur seulement. Pour le couper : /wlh rapports parcours off." }, en = { "Quests taken and turned in (with the guide step) and boss kills with their time go in a silent \"run\" report when you leave a dungeon (/wlh rapports parcours off stops it).", "" } },
    { s = "fix", fr = { "Clic sur l'étape en cours", "Cliquer sur la carte de l'étape pouvait donner une erreur quand la ligne du lieu était cachée." }, en = { "Clicking the current step no longer errors when its place line is hidden.", "" } },
    { s = "fix", fr = { "Flèches sur les sacs", "Avec beaucoup d'addons, le parcours de toutes les fenêtres du jeu dépassait le temps permis. Il se fait maintenant par petits morceaux." }, en = { "The bag arrows no longer hit \"script ran too long\" with many addons.", "" } },
  } },
  { v = "1.0.0-beta.191", date = "2026-11-22", items = {
    { s = "fix", fr = { "Sacs, « Libérer une place » ne jette plus ce qu'une quête demande", "Une quête de la Croisée demande des armes et des boucliers blancs, et le nettoyeur les jetait comme des objets inutiles. Un objet qu'un objectif de ton journal de quêtes demande (« Worn Shield : 1/5 ») reste maintenant dans tes sacs, qu'il soit blanc ou gris. La vente automatique des objets gris chez un marchand suit la même règle." }, en = { "Bags", "\"Free a slot\" and the grey item selling keep every item a quest of your log asks for." } },
  } },
  { v = "1.0.0-beta.190", date = "2026-11-22", items = {
    { s = "fix", fr = { "Les rapports arrivent enfin chez l'auteur de WL Helper", "Les rapports (« Nous écrire », erreurs automatiques, quêtes introuvables, mesures de mémoire) partaient vers le chef de guilde, qui ne les recevait pas, et n'arrivaient donc nulle part. Ils vont maintenant au personnage de l'auteur de l'addon, dès qu'il est connecté en même temps que le joueur. En attendant, ils restent en attente chez le joueur. Les rapports déjà en attente partiront tout seuls." }, en = { "Reports now go to WL Helper's author (they were addressed to the guild master and never arrived).", "" } },
  } },
  { v = "1.0.0-beta.189", date = "2026-11-22", items = {
    { s = "add", fr = { "Mesures de mémoire envoyées automatiquement", "Une fois par jour et par personnage, après 20 minutes de jeu, WL Helper envoie en silence un rapport à l'équipe WL Helper avec la mémoire de chacune de ses parties (le guide, WL Helper Gear, la navigation et ses cartes de déplacement), le total de tous les addons chargés, les 5 addons les plus lourds et ses opérations les plus lentes. Il passe par le même chemin que les rapports « Nous écrire » : la guilde seulement. Pour le couper : /wlh rapports memoire off." }, en = { "Once a day per character, a silent memory report goes to the WL Helper team through the guild (/wlh rapports memoire off stops it).", "" } },
    { s = "fix", fr = { "Notes de la beta.188", "La ligne « Champs de bataille, classement PvP de la guilde » n'apparaît plus qu'une fois, dans le changelog comme dans la fenêtre des nouveautés." }, en = { "The beta.188 notes no longer list the guild PvP ranking twice.", "" } },
  } },
  { v = "1.0.0-beta.188", date = "2026-11-22", items = {
    { s = "add", fr = { "Champs de bataille, classement PvP de la guilde", "Un onglet « Guilde » liste les membres qui ont WL Helper, avec leur rang PvP (titre du jeu, points dans l'infobulle), l'honneur de la semaine et du jour, les victoires de la semaine et leur rang dans les 4 factions de champ de bataille. Tri par honneur de la semaine (par défaut), par rang ou par victoires. Ta ligne est en évidence. Les chiffres viennent du jeu de chacun, partagés sur le canal de la guilde." }, en = { "Battlegrounds", "A Guild tab ranking the members with WL Helper by honor this week, rank or wins, with their battleground standings." } },
    { s = "add", fr = { "/wlh mem", "La mémoire prise par chaque partie de WL Helper (le guide, WL Helper Gear, la navigation et ses cartes de déplacement de chaque continent). La partie lourde, ce sont les cartes de déplacement des chemins à pied, chargées seulement quand le GPS dessine un chemin. Leur réglage (Réglages > GPS > Chemins à pied) le dit maintenant : coupé, elles ne sont jamais chargées." }, en = { "/wlh mem shows the memory each part of WL Helper takes; the walking paths setting says it is the heavy part.", "" } },
    { s = "add", fr = { "Guide de quête « Set de donjon 2 (T0.5) »", "Toute la chaîne du set de donjon 2 de ta classe, dans l'ordre. Elle part d'« Une proposition sérieuse » chez Deliana (Forgefer) ou Mokvar (Orgrimmar), puis passe par l'alambic ectoplasmique, « Une juste compensation », Anthion à Stratholme, « Le défi » aux Profondeurs de Rochenoire, « Les adieux d'Anthion », et l'amulette du seigneur Valthalak. Elle finit par « Garder le meilleur pour la fin ». La carte ne montre que les quêtes de ta classe et de ton camp. La dernière quête dit quelles pièces du set de donjon 1 rendre (tête et torse) et ce que tu reçois. Il faut un groupe pour les donjons. Les quêtes que les guides de donjon avaient déjà restent telles quelles. « Retourner voir Bodley », « Retour au commencement » et « Garder le meilleur pour la fin » sont nouvelles." }, en = { "Quest guide", "Dungeon Set 2 (T0.5), your class's whole chain from Deliana or Mokvar to Saving the Best for Last." } },
    { s = "add", fr = { "Hebdo : sac de l'Undermine", "Nouvelle carte dans l'onglet Quêtes pour la quête hebdomadaire du niveau 60 (Pix Xizzix, Baie-du-Butin) : un objet du dernier boss de chaque aile de Hache-Tripes, contre un sac avec un objet en or de 10 à 100 pièces." }, en = { "Weekly", "A Quests tab card for the level 60 weekly quest (Pix Xizzix, Booty Bay): an item from the last boss of each Dire Maul wing for an Undermine Satchel." } },
  } },
  { v = "1.0.0-beta.187", date = "2026-11-22", items = {
    { s = "add", fr = { "Guide des réputations", ", nouvel onglet « Réputations » de la fenêtre Meilleur équipement (/wlh rep, ou /wlh bis rep). Il liste toutes les réputations de ton camp : les villes, l'Aube d'argent, les Grumegueules, la Confrérie du thorium, le Cercle cénarien, les factions des champs de bataille et celles propres à Forever. Pour chacune :" }, en = { "", "" } },
    { s = "add", fr = { "", "ce que chaque rang débloque (pièces, montures, consommables, recettes), avec une coche sur les rangs que tu as déjà ;" }, en = { "", "" } },
    { s = "add", fr = { "", "ton rang, tes points et ce qu'il te manque ;" }, en = { "", "" } },
    { s = "add", fr = { "", "le plus rapide pour la monter, avec le nombre de fois à faire : objets à rendre (20 Pierres du Fléau de serviteur pour l'Aube d'argent : +25 par rendu, et combien tu en as déjà), quêtes répétables, quêtes pas encore faites, monstres. En tête, sous « Pour ton équipement », les réputations qui débloquent une pièce de ta liste (pré-BiS, BiS, PvP), et le rang marqué « pour ton équipement ». Un clic sur une carte met le GPS sur l'intendant. Les paliers, les objets à rendre et les quêtes viennent des données de Naowh, lues en direct. Les points par monstre viennent des pages Wowhead WoW Forever (Grumegueules, Aube d'argent, Cercle cénarien pour l'instant). Une façon de monter sans chiffre sourcé n'est pas affichée avec un chiffre. Les factions qui ne sont pas encore ouvertes sur Forever (Zandalar, Hydraxiens, Progéniture de Nozdormu) sont en bas, avec leurs récompenses seulement." }, en = { "Reputation guide", "A new \"Reputations\" tab in the Best gear window (/wlh rep) with every faction of your side, what each standing unlocks, your standing, and the fastest sourced way to raise it; those that unlock a piece of your list come first." } },
  } },
  { v = "1.0.0-beta.186", date = "2026-11-22", items = {
    { s = "add", fr = { "Guide de quête « Collier : Marque de Fordring »", "La chaîne de Tirion Fordring dans les Maleterres, 11 quêtes. Elle part de ses trois premières quêtes (Chiens-démons, Ciel couleur de sang, Larve putride), passe par Stratholme pour le tableau « De l'amour et de la famille », et finit par « En rêves » à Hearthglen. Il faut un groupe pour la fin. Sa récompense, la Marque de Fordring, est le collier que les simulations de Naowh classent premier pour 9 spés. Le Symbole de l'honneur perdu a maintenant sa position (Maleterres de l'Est)." }, en = { "Quest guide", "The Mark of Fordring chain (Tirion Fordring, Plaguelands), a neck ranked first for many specs." } },
    { s = "add", fr = { "« Cette quête n'existe pas sur Forever »", ", dans le menu de la vue moderne (groupe Étape) : la quête sort tout de suite de ta route, et un rapport avec son numéro part à l'équipe WL Helper par la guilde. Ça permet de nettoyer les guides à partir de ce que les joueurs trouvent en jeu." }, en = { "Modern view menu", "\"This quest is not on Forever\" takes it out of your route and reports it." } },
  } },
  { v = "1.0.0-beta.185", date = "2026-11-20", items = {
    { s = "chg", fr = { "Le guide n'a plus qu'une vue : la vue moderne.", "La grande fenêtre du guide ne s'ouvre plus, et tout ce qu'elle faisait passe par la vue moderne :" }, en = { "", "" } },
    { s = "chg", fr = { "", "la check-list ;" }, en = { "", "" } },
    { s = "chg", fr = { "", "les actions (recommencer la route, flèche GPS, raccourcis) ;" }, en = { "", "" } },
    { s = "chg", fr = { "", "la vue d'ensemble, les boss, la carte, le partage. /wlh guide, le bouton de la minicarte, l'accueil et le hub ouvrent la vue moderne, ou le choix de guide quand aucun guide n'est en cours. Le réglage « Vue moderne par défaut » disparaît." }, en = { "The guide has one view now", "The modern view. The old window never opens." } },
    { s = "fix", fr = { "WL Helper ne détourne plus les repères de Zygor", "Quand un de ces addons de guide est chargé, notre GPS ne suit plus les repères posés sur la carte, et WL Helper ne prend plus la commande /way. Tu peux remettre le suivi des repères dans les réglages du GPS (« Suivre les repères de la carte »)." }, en = { "WL Helper no longer takes over Zygor's or RestedXP's map pins and /way.", "" } },
  } },
  { v = "1.0.0-beta.184", date = "2026-11-20", items = {
    { s = "add", fr = { "Meilleur équipement, où trouver le patron", "Une pièce fabriquée dit où trouver son patron et le niveau de métier qu'il faut (« Patron : chez Qia (Berceau-de-l'Hiver) · métier 215 », « Patron : lâché par Pyromancien de Brandefeu · métier 295 », « butin aléatoire dans le monde », une quête, ou ton maître de métier). L'information vient du module Métiers de Naowh, lu en direct." }, en = { "Best gear", "Where to find a crafted piece's pattern, and the skill it needs." } },
    { s = "fix", fr = { "Meilleur équipement, des noms au lieu de numéros", "Une pièce que le jeu n'avait pas encore chargée s'affichait avec son numéro (« 18727 »). La fenêtre demande maintenant l'objet au jeu et se redessine dès qu'il arrive." }, en = { "Best gear", "Item names instead of numbers." } },
    { s = "fix", fr = { "« N choix » en gris", "Au lieu de rouge." }, en = { "\"N picks\" in grey, not red.", "" } },
  } },
  { v = "1.0.0-beta.183", date = "2026-11-20", items = {
    { s = "chg", fr = { "Vue moderne, les dernières actions de la grande fenêtre", "Son menu (roue dentée) a maintenant « Recommencer la route » (dans Guides, avec confirmation), « Flèche GPS » et « Raccourcis clavier » (dans Affichage). Tout ce que faisait le menu Actions de la grande fenêtre se fait désormais depuis la vue moderne." }, en = { "Modern view menu", "Restart the route, GPS arrow on/off, key bindings." } },
  } },
}
